        ['1.24.1', 'PvP Queue Timer Fix', 'Fixed the PvP matchmaking search timer resetting every few seconds instead of counting up, and fixed it not actually giving up after 5 minutes like it was supposed to.', 'fix', '2026-07-19 16:00:00'],
        ['1.24.2', 'Heal Skills No Longer Cost a Turn', 'Healing skills are now a free action in battle, just like potions — using one no longer hands the enemy a free attack.', 'fix', '2026-07-20 10:00:00'],
        ['1.24.3', 'Mobile Overhaul', 'Major mobile pass: fixed page headers overlapping the top bar on phones, shrunk the Report a Bug banner so it no longer sits on top of the menu button, stopped World Chat from overlapping other Dashboard cards while scrolling, and centered/tightened up Battle and Quests for small screens.', 'fix', '2026-07-21 10:00:00'],
        ['1.25', 'Changelog Page', 'Added this Changelog page and a live version tag in the sidebar, so you can always see what changed and what version the game is on.', 'feature', '2026-07-21 15:16:24'],
        ['1.25.1', 'Early-Game Difficulty Fix', "Fixed encounters letting low-level characters run into monsters meant for much higher levels (a level 1 character could occasionally get matched against a level-10 monster). Also fixed a few zone unlock levels that sat below their own weakest monster's level, leaving nothing to fight right after unlocking.", 'fix', '2026-07-21 16:30:00'],
        ['1.26', 'Invite Friends', 'Added a referral system: share your invite link or code, and every 5 friends who join and reach level 5 earns you 7 days of Gold VIP. Track your invite progress and rewards from the new Invite Friends page.', 'feature', '2026-07-21 17:00:00'],
        ['1.26.1', 'AdSense Verification', 'Added the Google AdSense site-verification script and ads.txt. No ads show yet — this just lets Google review the site; real ads go live only after approval.', 'misc', '2026-07-21 17:15:00'],
        ['1.26.2', 'Referral Fixes & Referee Bonus', 'Fixed referral codes being silently dropped on signup so they never actually linked accounts. Referred friends now also get their own reward: 300 gems the moment they reach level 5. The Invite Friends page now shows who referred you and your own progress toward that bonus.', 'fix', '2026-07-21 17:30:00'],
        ['1.26.3', 'Crafting Cost Rebalance', 'Fixed gathering tools (pickaxes, axes, sickles, hammers) being craftable for a small fraction of their shop price — some cost as little as 1/25th what the same item sold for. They now carry a gold fee in line with equivalent-tier weapons/armor. Also fixed equipped Hammers never losing durability while crafting (their crafting-speed bonus was already applying correctly, they just never wore down).', 'fix', '2026-07-21 18:15:00'],
        ['1.26.4', 'Region Rebalance', "Every region now has exactly 3 monsters plus a proper region boss, evenly spaced from that region's own unlock level up to the next region's. Previously several regions' monster levels overlapped into the next region (or went well past it), and three region bosses (Giant Spider, Frost Wyrm, Abyss Kraken) had no dungeon at all — meaning they weren't actually fightable. Every region boss now has its own dungeon.", 'balance', '2026-07-21 19:00:00'],
        ['1.27', 'No More Level Cap', 'Removed the level 150 ceiling — keep leveling as far as you want. Content unlocks stop around level 150 for now, but nothing stops you from grinding further.', 'feature', '2026-07-21 19:15:00'],
        ['1.28', 'Inventory Equipment Panel', 'Equipped gear now always shows its full stats, durability, and actions (unequip/repair/scrap) right on the slot — no more clicking to expand it first. Repair is also available for any damaged item, both equipped and in your bag.', 'feature', '2026-07-21 20:00:00'],
        ['1.28.1', 'Support Ticket Reply Fix', 'Fixed being unable to reply on a ticket once a GM marked it resolved/closed — replying now always works and reopens the ticket if needed.', 'fix', '2026-07-21 20:10:00'],
        ['1.29', 'Discord & Wiki Accuracy', 'Added a Join Discord link to the sidebar. Also fixed the Wiki\'s Zones, Dungeons, Skills, Classes, and Events pages showing outdated/placeholder info — they now stay in sync with the real game data automatically.', 'feature', '2026-07-21 20:20:00'],
        ['1.29.1', 'Skill Tree Messaging Fix', 'Fixed the Skill Tree showing a misleading "Requires level X" on a skill you already qualify for — that message only shows up when level is actually the blocker; otherwise it correctly tells you how many skill points you need.', 'fix', '2026-07-21 20:30:00'],
        ['1.30', 'Warrior Shield Slot & Mastery Skills', "Warriors now equip a Shield alongside their chest armor — a real 2nd defensive slot, not just flavor. Every class also gained a Mastery skill unlocked by choosing a Lv.20 profession, not just reaching the level.", 'feature', '2026-07-21 21:00:00'],
        ['1.30.1', 'Crafting Overhaul', "Crafting gear now costs noticeably more resources (each tier draws from a single material, like repair packs already did) and takes longer, while repairing damaged gear got cheaper and more reliable — keeping a good roll is now clearly better than scrapping and rerolling. Crafted gear also shows its exact roll % everywhere (Crafting, Inventory, Marketplace), and both Luck and Crafting rank now push that roll higher. Every class has a full, clean 5-tier weapon and armor lineup.", 'balance', '2026-07-21 21:15:00'],
        ['1.30.2', 'Class-Locked Equipping', "You can no longer equip gear made for another class — the Equip button on gear that isn't yours now offers to list it on the Marketplace instead.", 'fix', '2026-07-21 21:20:00'],
        ['1.31', 'VIP Cancel & Marketplace Search', "Added a Cancel Subscription button to VIP — cancelling keeps your perks until the current period ends and simply stops the next charge; resubscribing before then doesn't charge you again. Also added search to Inventory and the Marketplace, and you can now cancel your own Marketplace listing early for a 10% fee.", 'feature', '2026-07-21 21:30:00'],
        ['1.32', 'Repair Rolls & New Brews', "Repair packs now roll a bit better or worse each use, just like crafting — so luck plays a part in how much durability you get back. Also added a full line of brewable Mana potions and higher-grade Regen tonics (Moonpetal, Sunroot, and Phoenix tier) to Crafting, alongside the existing Health potions.", 'feature', '2026-07-21 22:00:00'],
        ['1.33', 'Marketplace Listing Cap & Referral Code Refresh', "Active Marketplace listings are now capped at 10 per character — VIP raises that to 15 (Bronze), 20 (Gold), or 30 (Diamond), shown right on the My Listings tab. Your listing history is trimmed to your most recent 30. Also refreshed everyone's referral code to a new, permanent format tied to your account — check the Referrals page for your new code if you'd shared the old one.", 'feature', '2026-07-21 22:15:00'],
        ['1.33.1', 'Crafting Queue Shows Stats', "Items sitting in your Crafting queue now show their stats (ATK/DEF, heal %, regen bonuses, etc.) while they're brewing, not just before you queue them.", 'fix', '2026-07-21 22:20:00'],
        ['1.34', 'Legend of Solyx Title', "If you played the original Discord-bot version of Solyx, link your Discord account in Settings — if it matches our records, you'll automatically receive the exclusive \"Legend of Solyx\" title.", 'feature', '2026-07-22 09:00:00'],
        ['1.34.1', 'Lifesteal Now Works', "Lifesteal gear was showing on the Wiki but never actually did anything in battle — fixed, and every heal-back now shows in your battle log.", 'fix', '2026-07-22 09:10:00'],
        ['1.34.2', 'Consistent Emoji Everywhere', "Switched every emoji in the game to Twemoji so icons look the same for everyone, regardless of device or OS.", 'misc', '2026-07-22 09:15:00'],
        ['1.35', 'Potions in PvP', "You can now drink a healing potion mid-PvP-match — same as in regular battles, it's a free action that doesn't cost you your turn.", 'feature', '2026-07-22 09:20:00'],
        ['1.35.1', 'PvP Matchmaking Fix', "Fixed two bugs keeping players from finding real matches: the Rivals list required an exact rank match that could leave it empty even with plenty of fair opponents around, and matchmaking's search radius wasn't widening fast enough to pair players with a bigger rating gap before giving up.", 'fix', '2026-07-22 09:30:00'],
        ['1.35.2', 'PvP Live Match Fix', "Fixed a bug where a live PvP match could suddenly claim it \"belongs to different characters\" mid-fight and get stuck — it now always finds your fighting character correctly, no matter what else you're doing on your account at the same time.", 'fix', '2026-07-22 09:40:00'],
        ['1.35.3', 'Gem Economy Overhaul', "Complete gem economy rebalancing: gem packs now grant more gems for the price (with +10% bonus displayed as a ribbon), Auto-Attack 60min pass is now €0.99, and all rare/epic/legendary/mythic items repriced to match new rates (Rare: 250+ gems, Epic: 500+, Legendary: 2000+, Mythic: 4000+).", 'balance', '2026-07-22 10:00:00'],
        ['1.35.4', 'Level & XP System Rework', "Levels are now calculated from your XP in real-time on the Dashboard (always accurate), while the stored level is kept only for database queries. Fixed XP display showing 0/0 for level 1 characters. Also added a one-time level recalculation — if your stored level didn't match your XP, it's been corrected and your attribute/skill points adjusted accordingly (negative points = debt that clears as you level back up).", 'balance', '2026-07-22 10:10:00'],
        ['1.35.5', 'Battle Log Improvements', "Battle logs now properly update with XP gains after every fight, and character data refreshes immediately after battle completion so the Dashboard always shows current stats.", 'fix', '2026-07-22 10:15:00'],
        ['1.36', 'Shop Tier System & Unlock Clarity', "Shop now shows all item tiers at once instead of hiding higher tiers. Two unlock systems work together: Level unlock (item min_level) lets you buy with gems, Crafting unlock (tier level) lets you buy with gold. Consumables are now organized by type (HP/MP/Regen) in both Shop and Crafting. All craftable consumables (herbal, sage, moonpetal, sunroot, phoenix) are now purchasable with proper tier-based pricing.", 'feature', '2026-07-22 10:20:00'],
        ['1.37', 'Gear Durability Warnings', "Battle now alerts you when equipped gear is broken (0% durability - red alert) or running low (≤20% - orange alert). Warnings update automatically when you repair gear, no page reload needed.", 'feature', '2026-07-22 10:25:00'],
        ['1.37.1', 'Economy Balance', "Rebalanced monster economy rewards with lower gold gains and reduced gem payouts, Consumable healing was also adjusted by tier (including support for flat+percent healing where intended)", 'balance', '2026-07-23 12:00:00'],
        ['1.38', 'Referral Code Update', "Referees only need 2 referrals to receive 7 days of Gold VIP and referrals now grant 500 gems to the referred friend (up from 300) when they reach level 5, and the Invite Friends page now shows your own progress toward that bonus.", 'feature', '2026-07-23 12:30:00'],
        ['1.39', 'landing page stats', "Added total quests and total items to the landing page stats, alongside adventurers, playable classes, and zones/dungeons.", 'feature', '2026-07-23 12:45:00'],
        ['1.40', 'Store Payment Method Update', "Store now uses Stripe's automatic payment methods instead of hardcoding card-only payments, allowing for more payment options in the future.", 'feature', '2026-07-23 13:00:00'],
        ['1.41', 'Password Reset Email Redesign', "Reset-password emails now match Solyx's actual look — dark themed and branded with our logo instead of the generic default template.", 'feature', '2026-07-24 09:00:00'],
        ['1.42', 'Faster, Less Laggy Gameplay', "The game now runs on a single smooth heartbeat instead of a pile of separate timers, with gathering and background checks batched together behind the scenes — less network chatter, snappier feel, especially noticeable on slower connections.", 'feature', '2026-07-25 09:00:00'],
        ['1.43', 'Auto battle Runs Non-Stop, Auto-Gather Gets a Target Switch', "Auto-Battle keeps running in the background at all times, even while you're fighting manually — it's fully risk-free (no HP, mana, potions, or durability lost) and still pays out real gold and XP on a win. Also fixed Auto-Gather sometimes under-delivering materials when your tools or luck should've boosted the yield, and you can now switch Auto-Gather's target resource mid-run without losing any progress.", 'feature', '2026-07-26 09:00:00'],
        ['1.44', 'Live HP/MP/Energy Bars', "Health, mana, and energy now animate smoothly in real time as they regen, everywhere they're shown — instead of only jumping to a new number after a reload or your next action.", 'feature', '2026-07-27 09:00:00'],
        ['1.44.1', 'Accurate HP After Battle', "Fixed HP snapping to the wrong number right after winning, losing, or reviving mid-fight — it now always matches exactly what was shown during the battle, and the Dashboard stays in sync with your HP live while you're fighting.", 'fix', '2026-07-27 09:10:00'],
        ['1.44.2', 'HP/MP No Longer Revert on Reload', "Fixed HP/MP occasionally reverting to an old value after reloading the page — the game now saves exactly what you were shown a moment before, instead of the server silently recalculating its own (sometimes different) number.", 'fix', '2026-07-27 09:20:00'],
        ['1.44.3', 'Mana No Longer Refills Mid-Fight', "Fixed mana visually topping back up on its own during battle right after a skill spent it — mana regen is correctly paused for the whole fight now, same as it already was meant to work, so skill costs actually stick until you win, heal, or drink a potion.", 'fix', '2026-07-27 09:30:00'],
        ['1.45', 'Inventory Reorganized', "Your Bag is now grouped into categories exactly like Shop and Crafting — Weapons, Armor, Quivers, and Tools first, then Consumables (split by HP/MP/Regen), Repair Packs, Cosmetics, and Materials. Within each gear category, anything your class can actually equip now sorts ahead of gear made for another class.", 'feature', '2026-07-27 10:00:00'],
        ['1.46', 'PvP Search Runs in the Background', "Find Match no longer strands you on a spinner — hit it and keep playing anywhere in the game. A small ⚔ timer stays in the top bar the whole time it's searching (with its own cancel button), and the moment an opponent is found you get a toast and get pulled straight into the arena.", 'feature', '2026-07-27 10:30:00'],
        ['1.46.1', 'PvP Search Timer No Longer Rewinds', "Fixed the background search timer visibly ticking backward by a second every time it checked in with the server — it now counts up smoothly the whole time you're queued.", 'fix', '2026-07-27 10:40:00'],
        ['1.47', 'PvP Leaderboard Replaces Direct Challenges', "Challenging a specific rival is gone — matchmaking is now the only way into a match. In its place, the Arena lobby shows a live PvP leaderboard, with your own rank called out even when you're outside the top of the list.", 'feature', '2026-07-27 10:50:00'],
        ['1.47.1', 'PvP Arena Polish', "Finding a match no longer swaps out the whole Arena screen — Find Match just turns into a small live timer in place, same spot, so the rank card and leaderboard stay right where they are while you search. The PvP leaderboard also now shows titles, name colors, icons, and VIP badges, same as everywhere else you show off your look.", 'fix', '2026-07-27 11:00:00'],
        ['1.48', 'Gathering & Crafting Timers in the Top Bar', "Auto-Gather and your Crafting queue now show a live countdown in the top bar too, same idea as the PvP search timer — start a gather pass or queue a craft, then go do anything else in the game and watch it tick down without needing to sit on that page. A separate badge lights up the moment a craft is ready to collect.", 'feature', '2026-07-27 11:10:00'],
        ['1.48.1', 'Energy Now Animates Live', "Your Energy bar on the Gathering page used to only update after each action or a page reload — it now climbs smoothly in real time like HP and Mana already did everywhere else, and gather buttons correctly re-enable the moment you actually have enough Energy again instead of waiting on a stale number.", 'fix', '2026-07-27 11:20:00'],
        ['1.48.2', 'Gathering Rebalance', "Gathering actions now take longer overall, and higher-tier nodes (Mythril Ore, Moonwood, Phoenix Bloom, etc.) take noticeably more time per action than early nodes on top of that — gathering rank, Speed attribute points, and tools still cut this down same as before. Also fixed Smelting's bars unlocking before their matching ore was even mineable — every Smelting tier now unlocks at exactly the same level as the ore it melts.", 'balance', '2026-07-27 11:30:00'],
        ['1.48.3', 'Live HP/Mana/Energy Bars Could Silently Freeze', "Fixed a bug where the live-updating HP/Mana/Energy numbers could permanently stop refreshing after navigating between certain pages, leaving stale bars until you reloaded the whole game — the background timer driving them now keeps running for your entire session no matter where you go.", 'fix', '2026-07-28 09:00:00'],
        ['1.48.4', 'Smelting Was Impossible to Unlock', "Our last Smelting fix overcorrected: Iron Bar ended up requiring Smelting level 8, but Smelting only gains levels from smelting — there was no way to ever reach it. Smelting's own level requirement is back to 1 for Iron Bar (same as every other skill's starting tier), and it also now correctly requires Mining level 8 so you still need to actually be able to mine the ore first.", 'fix', '2026-07-28 09:10:00'],
        ['1.48.5', 'Higher-Tier Gathering Takes Even Longer', "Doubled the extra time added per gathering tier — a Mythril/Moonwood/Phoenix Bloom-tier node now takes considerably longer per action than a starting node, on top of the flat time-per-action increase from the last gathering update.", 'balance', '2026-07-28 09:20:00'],
        ['1.48.6', 'Gathering Feels Snappier', "Queued gather clicks now flush to the server almost instantly instead of sitting on 'Queued…' for up to several seconds, and Energy now visibly drops the moment you click instead of waiting for that round trip to finish.", 'fix', '2026-07-28 09:30:00'],
        ['1.48.7', 'Gathering Tiers Take Much Longer', "Raised the extra time added per gathering tier again — the gap between a starting node and a top-tier one (Mythril Ore, Moonwood, Phoenix Bloom, Mythril Bar) is now much larger, on top of gathering's already-doubled base time.", 'balance', '2026-07-28 09:40:00'],
        ['1.48.8', 'Energy Regen Halved', "Passive Energy regeneration now trickles in at half the old base rate — level, Energy Regen attribute points, and VIP bonuses all still add on top of that as before.", 'balance', '2026-07-28 09:50:00'],
        ['1.49', 'Gathering Cooldown Shown in the Top Bar', "Working a Mining, Woodchopping, Foraging, or Smelting node now also shows a live countdown pill in the top bar, same as Auto-Gather and Crafting — go do anything else in the game while your longest-running gather cooldown ticks down in view.", 'feature', '2026-07-28 10:00:00'],
        ['1.50', 'Auto-Battle Timer Shown in the Top Bar', "Training now also shows a live countdown pill in the top bar, same as Auto-Gather, Crafting, and the manual gathering cooldown — go do anything else in the game while it ticks down in view.", 'feature', '2026-07-28 10:10:00'],
        ['1.50.1', 'Topbar Timers Could Silently Drain Energy/HP', "Fixed a bug where the Auto-Gather and Auto-Battle top-bar timers were quietly ticking gathering/fights forward on every page just by being on screen — spending Energy or HP/MP even while you were nowhere near the Gathering or Battle page. Both pills are now pure countdown displays; only actually visiting Gathering or Battle advances them.", 'fix', '2026-07-28 10:20:00'],
        ['1.51', 'Companions Can Now Rank Up', "Companions max out at level 10 instead of 25 — hit it, and Rank Up resets their level back to 1 in exchange for a permanent +25% bonus and a higher level cap, repeatable up to Rank 50. Leveling itself no longer boosts a companion's bonus — only ranking up does. Rank Up costs gold (scaled to the companion's own unlock cost), plus a small gem top-up for companions originally unlocked with gems, both rising 10% each rank.", 'feature', '2026-07-28 10:30:00'],
        ['1.52', 'A Dozen New Leaderboards', "The Leaderboard now tracks way more than Power, Level, Trophies, Monsters Slain, Gold, and Deaths — new boards for Boss Slayer, Gem Hoarder, Quest Completionist, Master Miner, Lumberjack, Forge Master, Herbalist, Master Crafter, Dungeon Delver, Companion Collector, and Companion Master. Falling outside the top 100 no longer means you vanish from the board either — your own row and exact rank now show below the cut, same idea as the PvP Arena.", 'feature', '2026-07-28 10:40:00'],
        ['1.53', 'Leaderboard Seasons, Guild & Friends Boards, and Rewards', "The Leaderboard is now a real seasonal ladder: a 30-day season with a live countdown, Weekly/Daily/All-time range tabs, and a Global/My Guild/Friends scope switch on every board. A new Guild Power board ranks guilds by combined member strength. Finishing in the top 100 at season's end now pays out real gold, gems, and exclusive title/banner rewards, with past champions archived forever in a new Hall of Fame — and your Friends list doubles as a built-in rivals tracker, showing exactly how far ahead or behind each friend you are on whichever board you're viewing.", 'feature', '2026-07-28 10:50:00'],
        ['1.53.1', 'Trophies Is Now the Default Leaderboard', "PvP Trophies is now the leaderboard you land on, and it now supports Weekly/Daily/Season range tabs too — showing rating gained over that window instead of just your all-time rating. Season reward payouts at season's end are now also ranked by Trophies, not Power. Seasons are simpler too: no more flavor names, just 'Season N', and each one now runs for a calendar month instead of a fixed 30 days.", 'balance', '2026-07-28 11:00:00'],
        ['1.54', 'Battle Pass Overhaul: Quest-Only Progress, Bigger Rewards', "The Battle Pass no longer fills up from grinding or auto-battling monsters — every bit of progress now comes from completing quests (dailies, weeklies, monthlies, and the one-time story/class/raid quests), each worth its own amount depending on how much effort it represents. Maxing all 100 tiers is a real season-long push now, not a half-hour session. Rewards are bigger and scale harder too: steeper gold every tier, escalating gem payouts, bigger repair pack and ore bundles, and Premium now also unlocks two exclusive cosmetics — the 'Battle Pass Veteran' banner at tier 50 and the 'Battle Pass Champion' title at tier 100. Premium's gear stays identical rarity to the free track on purpose — better currency and exclusive flair, never combat power.", 'balance', '2026-07-28 11:10:00'],
        ['1.55', 'Battle Pass Redesign: Built-In Quest Tracker & VIP Points Bonus', "The Battle Pass page has been redone with a proper reward-track overview, a built-in quest tracker so you can see and claim your Daily/Weekly/Monthly/Main/Raid quests without leaving the page, and a new 'How You Earn Points' breakdown showing exactly where a season's worth of points comes from. Rewards lean much harder into crafting materials now instead of pure currency, gold payouts are 10x higher at every tier, and quest reward chips now call out Battle Pass Points by name. Active VIP subscribers also earn bonus points on every quest that grants them — +5% Bronze, +10% Gold, +20% Diamond.", 'feature', '2026-07-28 11:20:00'],
        ['1.56', 'Battle Pass Is Now Monthly', "The Battle Pass season is now a real 30-day month, and its points curve has been retuned so a dedicated player can reach tier 100 within just the first 25 of those days doing nothing but daily/weekly/monthly quests — 5 days of guaranteed slack built in, not a requirement to complete every single one perfectly.", 'balance', '2026-07-28 11:30:00'],
        ['1.57', 'Battle Pass & Quest Clarity Fixes', "Reward tiles on the Battle Pass track now show the correct icon and name for what you're actually getting instead of a mismatched or cut-off jumble when a tier grants several things at once — hover a tile for the full breakdown. The page also shows a proper loading skeleton on first open instead of a blank flash. The 8 'Unlock [skill]' quests now say exactly which character level unlocks that skill instead of leaving it unexplained.", 'fix', '2026-07-28 11:40:00'],
        ['1.58', 'Battle Pass Seasons Now Match Real Months, Plus a Tier 100 Jackpot', "The Battle Pass season is now the actual current calendar month (28-31 days, whatever the month is) instead of a fixed length, and the page has a new progress card up top showing your tier, points banked toward the next one, season total, and a real pace projection toward tier 100 based on your own actual progress. Resource rewards now rotate through every rarity all the way down to the humble starter material at every tier — even a late tier can still hand you plain Stone alongside the good stuff, nothing ages out of the pool entirely. Tier 100 now pays out a one-time jackpot on top of the usual reward: 1,000,000 gold and 1,000 gems on Premium (half that on Free). Premium itself now costs 1000 gems or €4.99 — matched exactly to the going gem-pack rate instead of an arbitrary price.", 'balance', '2026-07-28 11:50:00'],
        ['1.59', "Battle Pass Header Now Shows Days Left, Unlock Premium Pitch Fixed", "The Battle Pass header now shows how many days are left in the season, same idea as the Leaderboard. The 'Unlock Premium' pitch card was overstating its case — it was adding up Premium's full reward total, which already includes the same baseline value the Free track gives you, so buying Premium looked like it was worth more than it actually adds on top. It now shows only what Premium genuinely adds beyond Free.", 'fix', '2026-07-28 12:00:00'],
        ['1.60', "Leaderboard and PvP Seasons Now Match Real Calendar Months", "Leaderboard seasons now run from the 1st to the last day of the actual calendar month (28-31 days) instead of a rolling 30 days from whenever the season happened to start. PvP seasons, already resetting on the 1st of every month, now also auto-advance their season number and title rewards each month instead of being stuck handing out the same 'Season 1' titles forever.", 'fix', '2026-07-28 12:10:00'],
        ['1.61', "Battle Pass Gold & Gem Totals Fixed to the Real Numbers", "The Battle Pass' Premium gold and gems were stacking a per-tier payout on top of a separate tier-100 jackpot, overshooting the intended season totals. Premium now pays out exactly 1,000,000 gold and exactly 1,000 gems across the full season (Free gets exactly half of each), with the payout still ramping up toward the higher tiers rather than being spread flat. The 'Unlock Premium' pitch card is now collapsed to gold/gems/a resource-count summary by default, with a button to expand the full resource breakdown, and no longer lists gear or cosmetic rewards.", 'fix', '2026-07-28 12:20:00'],
        ['1.62', "Battle Pass Premium Is Now Payment-Only, Resource Rewards Corrected", "Premium can no longer be unlocked with gems — it's a real-money purchase only now, so the 1000-gem unlock button is gone. Raw material and ore-bar reward quantities have also been corrected to their intended amounts (1,028 common / 256 rare / 64 epic / 32 legendary / 16 mythic per drop, bars matching their ore's rarity), replacing an earlier guessed set of numbers that didn't match.", 'balance', '2026-07-28 12:30:00'],
        ['1.63', "Battle Pass Reward Totals Are Now the Exact Season Numbers", "Every material, ore bar and repair pack reward on the Premium track now totals exactly the intended amount across the whole season (e.g. 1,028 Stone, 512 Iron Ore, 256 Silver Ore, 64 Gold Ore, 16 Mythril Ore, and the matching numbers for every other resource and repair-pack rarity), split evenly across however many tiers actually grant that item — instead of a flat per-tier amount that didn't add up to the intended total. Free is exactly half of every one of these numbers. Gems are no longer trickled out across the season — tier 100 alone now grants a lump 1,000 gems on Premium (500 on Free), exactly refunding what Premium costs in gems. The 1000-gem Premium unlock option is back alongside the €4.99 cash purchase. The 'Unlock Premium' card now shows Premium's own full totals (not a comparison against Free), matching these numbers exactly.", 'balance', '2026-07-28 12:40:00'],
        ['1.64', "Battle Pass Points Added to the Leaderboard, Every Category Now Crowns a Champion", "Battle Pass Points is now a leaderboard category, ranking everyone by total points earned this pass. And every single leaderboard category — not just Trophies — now crowns its own permanent titles at each season's end: rank 1 gets 'Champion of [Category]', ranks 2 through 10 get 'Top 10 in [Category]'. These are yours to keep forever once earned, even after you drop out of the ranking the following month.", 'feature', '2026-07-28 12:50:00'],
        ['1.65', "Leaderboard Range Tabs Reordered, Now Show Gained vs Current, Season Rewards Match the Category", "Range tabs are now ordered Day, Week, Season, All-Time, and each is labeled 'Gained' or 'Current' depending on the stat: Trophies is the only stat that actually resets (each PvP season), so it always shows your current rating no matter which tab you pick; every other stat — including Power and Battle Pass Points, which previously only showed a single live number — now shows real gains for that window, same as Gold always has. The Season Rewards card also now describes the actual reward for whichever category you're viewing instead of always showing the Trophies payout — most categories are title-only (Champion/Top 10), only Trophies pays out gold and gems.", 'feature', '2026-07-28 13:00:00'],
        ['1.66', "Profile Page Overhaul: Avatar Frames, Equipped Loadout, Rankings & More", "Your profile now shows a lot more of what you've actually earned: an Equipped Loadout card, real Rankings (Level, Trophies, Battle Pass Points, Richest), a Recent Activity feed (achievements, duels, cosmetic unlocks), your Guild card, and a Season History summary — all real data, nothing fabricated. Avatar Frames are a brand new cosmetic type alongside titles/colors/banners/icons — a couple are gem-purchasable, one unlocks at character level 60, one for defeating the Ashfang Dragon, one from Battle Pass tier 75, and a mythic one for reaching Master in PvP. Equipped banners and frames now show their name as a visible tag on your profile (and everyone else's) instead of only being visible from the Customize screen. You can also pin up to 3 earned achievements to showcase at the top of your Trophy Case. Viewing another player now shows a real Head-to-Head duel record between you and them.", 'feature', '2026-07-28 13:10:00'],
        ['1.67', "Profile Page: One Continuous Page, Real Top Rankings, Most Difficult Enemies & More", "Stats and Achievements are no longer separate tabs — everything now lives on one scrolling Overview page, and Customize is reached from the hero's \"Edit profile\"/\"Change banner\" buttons instead of a tab. Rankings now show whichever 4 boards you actually rank best in out of all 18 categories, instead of a fixed set. Added a real \"Most Difficult Enemies\" panel showing the monster and rival player who've beaten you the most. Recent Activity is windowed to the last 7 days and reads cleaner (bolded names, relative timestamps like \"2h ago\"). Trophy Case now shows 5 trophies with how you actually earned each one. You can now write a short bio and pick up to 4 playstyle tags, both shown on your hero and public profile. The Customize screen groups every cosmetic — titles, colors, banners, icons, avatar frames — by how it's actually unlocked (Achievements, Battle Pass, Quests, or Bought), and added dozens of new gem-purchasable colors, banners, icons, frames and titles to buy. Also fixed the Gold quick-stat rendering in purple instead of gold.", 'feature', '2026-07-29 10:00:00'],
        ['1.67.1', "Profile Polish: Level XP Bug, Overlapping Buttons, Locked Cosmetics & a Real History Graph", "Fixed the hero's XP bar showing lifetime XP instead of progress toward your next level. Fixed the hero's action buttons visually overlapping the equipped banner/frame tags. Trophy Showcase (picking which achievements to feature) has moved into Customize instead of cluttering the Overview page with every achievement you own. Replaced the placeholder stat cards with a real chart of any leaderboard category's history over time (pick from a dropdown), pulled from the same daily snapshots the leaderboard itself uses. Locked cosmetics in Customize now show their real look (dimmed) with a \"Locked\" badge and how to earn them, instead of hiding behind a blank \"???\" card. Fixed a bug where a couple of Battle Pass-only cosmetics could be \"unlocked\" for free and showed as Free in Customize — they're correctly locked behind reaching that Battle Pass tier now.", 'fix', '2026-07-29 14:00:00'],
        ['1.68', "Character Renames, Combat Comparison & Season Leaderboard Banners", "You can now rename your character for 1,000 gems from Edit Profile — no free tier or cooldown, just a flat cost. Combat Profile now shows how your Attack, Defense, HP, Crit Chance and Dodge Chance compare to other players within 5 levels of you, not just your own base/total breakdown. Every leaderboard season, finishing in the top 100 of any category now earns a permanent \"season banner\" for that exact placement — hold several across different boards and seasons at once (an old Season 1 Gold #1 banner stays yours even after a new one from Season 3 comes in), browsable in Customize with board filters. Trophy Showcase can now feature up to 5 achievements instead of 3.", 'feature', '2026-07-29 16:00:00'],
        ['1.68.1', "Quick Stats Spacing, All Achievements Returns & an Unlock Exploit Closed", "Fixed the Quick Stats row leaving an empty gap at the end instead of stretching to fill it. Recent Activity now shows a connecting line down the timeline between entries. Restored a full \"All Achievements\" browsing section to the Overview page — Trophy Case up top stays a focused, hand-picked showcase. Removed the redundant \"Change banner\" hero button since it's already reachable from Edit Profile. Closed a gap where a batch of leaderboard title and banner rewards could be unlocked for free instead of only being earned through real placement — existing rewards were corrected in place, nobody loses what they legitimately earned.", 'fix', '2026-07-29 16:30:00'],
        ['1.69', "Level Milestone Referral Rewards", "Referral rewards now trigger at multiple level milestones: Level 5 still grants 7 days of Gold VIP to the referrer (per 2 users), but now Level 10, 25, 50, 100, 150, 200, 250 and every 50 levels beyond grant 100 gems instead (also per 2 users reaching each milestone). Each milestone tracks separately, so 2 friends hitting level 10 earns you gems, then those same 2 hitting level 25 earns gems again, and so on. The Invite Friends page now displays progress toward each milestone tier.", 'feature', '2026-08-01 21:00:00'],
        ['1.70', "Account-Wide Gems", "Gems are now shared across all characters on your account instead of being tied to individual characters. All your existing character gems have been combined into one account-wide pool that any character can spend. This encourages playing multiple characters — run dungeons with each to maximize your gem earnings! The Dungeons page now displays a helpful hint about this change.", 'feature', '2026-08-01 21:10:00'],
        ['1.70.1', "Post-Launch Fixes", "Fixed gems not updating in the top-bar after earning or spending them — the navbar now always reflects your current gem balance. Fixed Leaderboard season banners mixing up rank 2 and rank 3 (they now show the correct placement label). Fixed a crash in the leaderboard reward distribution that could silently skip rewards for some players. Also fixed a small display issue on the Referrals page showing milestone progress.", 'fix', '2026-08-02 21:00:00'],
        ['1.71', "8h Overnight Auto-Battler & Auto-Gatherer", "Added an 8-hour overnight Auto-Battle and Auto-Gather pass for €0.99 — queue it before bed and come back to a full night of progress. Also fixed the gem pack purchase buttons occasionally not responding on the Gem Store page.", 'feature', '2026-08-05 20:58:00'],
        ['1.71.1', "VIP Tier Bonus Rebalance", "VIP tier bonuses have been rebalanced to cleaner values: Bronze 25%, Gold 50%, Diamond 100%. The 1-hour Auto-Battle and Auto-Gather passes have been removed from the Gem Store — the 8-hour overnight pass (€0.99) and the longer timed passes remain available.", 'balance', '2026-08-05 21:10:00'],
        ['1.72', "4 New VIP Perks", "All VIP tiers gained four new perks: a Daily Gem Bonus (bonus gems from your daily reward claim), an Auto-Pass Duration Boost (longer auto-battle and auto-gather sessions), a Marketplace Fee Reduction (lower cut on your sales), and a Gather Speed Boost (faster resource collection per cycle). Higher tiers get bigger bonuses across all four.", 'feature', '2026-08-05 21:19:00'],
        ['1.72.1', "Marketplace Fee & VIP Economy Rebalance", "The Marketplace sale fee has been raised from 5% to 10% to better reflect a healthy player economy. VIP fee reductions have been rebalanced across all tiers to remain meaningful at the new baseline. Diamond VIP members also gained a new Gather Yield perk, increasing the amount of resources collected per auto-gather cycle.", 'balance', '2026-08-05 21:29:00'],
        ['1.72.2', "VIP Cancel-Fee Discount & Marketplace UI", "The VIP fee reduction now also applies to the early cancel fee on your own Marketplace listings (previously only applied to sale fees). The Marketplace page and VIP perks page both now display the current fee rates and exact VIP discounts clearly, so you always know what you'll actually pay.", 'balance', '2026-08-06 06:56:00'],
    ];

    /** Keyed on version, not create() — re-running db:seed on live must never duplicate or reset
     * GM-edited changelog entries. */
    public function run(): void
    {
        foreach (self::ENTRIES as [$version, $title, $body, $tag, $publishedAt]) {
            Changelog::firstOrCreate(
                ['version' => $version],
                ['title' => $title, 'body' => $body, 'tag' => $tag, 'published_at' => $publishedAt]
            );
        }
    }
}
